import{_ as a,o as t,c as s,a3 as r}from"./chunks/framework.rQcsxYkC.js";const m=JSON.parse('{"title":"What is Arc Names","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-arc-names.md","filePath":"guide/what-is-arc-names.md","lastUpdated":1785888355000}'),n={name:"guide/what-is-arc-names.md"};function o(i,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="what-is-arc-names" tabindex="-1">What is Arc Names <a class="header-anchor" href="#what-is-arc-names" aria-label="Permalink to &quot;What is Arc Names&quot;">​</a></h1><p>Arc Names is a naming service for the Arc network. It maps a human-readable name — <code>alice.arc</code> — to the things a wallet address can&#39;t express on its own: where to send funds, what avatar to show, which website belongs to whom.</p><p>If you have used ENS on Ethereum, Arc Names will be immediately familiar. It follows the same registry → resolver architecture, the same namehash algorithm, and the same reverse-record convention for primary names.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>A raw address is 42 characters of hexadecimal. It is unreadable, unmemorable, and impossible to verify by eye — <code>0xCA78…8978</code> and <code>0xCA78…8979</code> look identical at a glance, and one of them loses your funds.</p><p>A <code>.arc</code> name replaces it:</p><table tabindex="0"><thead><tr><th>Without a name</th><th>With a name</th></tr></thead><tbody><tr><td><code>0x3dC38247c4f9672B2C98aCfdc5C1302f8d897E9C</code></td><td><code>alice.arc</code></td></tr><tr><td>Copy-paste only, verify character by character</td><td>Type it, read it, say it out loud</td></tr><tr><td>Changing wallets means telling everyone a new address</td><td>Point the name at the new wallet; nothing else changes</td></tr></tbody></table><p>That last row matters more than it looks. A name is a layer of indirection you control. The name is the stable identifier your contacts and apps hold onto — the address behind it is yours to change whenever you like.</p><h2 id="what-a-name-actually-is" tabindex="-1">What a name actually is <a class="header-anchor" href="#what-a-name-actually-is" aria-label="Permalink to &quot;What a name actually is&quot;">​</a></h2><p>Three things at once, and it helps to keep them separate:</p><ol><li><strong>An ERC-721 token.</strong> Registering mints an NFT to your wallet. The token ID is derived from the name itself. Owning that token <em>is</em> owning the name — you can transfer it, sell it, or hold it. See <a href="/docs/guide/ownership.html">Ownership &amp; transfers</a>.</li><li><strong>A registry entry.</strong> The registry records which resolver contract answers questions about your name. See <a href="/docs/protocol/resolving.html">Resolving .arc</a>.</li><li><strong>A set of records.</strong> Address, avatar, website, social handles, stored on the resolver and readable by any app. See <a href="/docs/guide/records.html">Records &amp; profile</a>.</li></ol><p>Registering gets you the token. The registry entry and the records are set up afterwards, and the app walks you through both.</p><h2 id="what-you-can-do-with-one" tabindex="-1">What you can do with one <a class="header-anchor" href="#what-you-can-do-with-one" aria-label="Permalink to &quot;What you can do with one&quot;">​</a></h2><ul><li><strong>Receive payments.</strong> Anyone can send to <code>alice.arc</code> in a wallet that supports Arc Names.</li><li><strong>Be identified.</strong> Set it as your <a href="/docs/guide/primary-name.html">primary name</a> and apps will display <code>alice.arc</code> instead of <code>0x3dC3…7E9C</code> wherever your address appears.</li><li><strong>Publish a profile.</strong> Avatar, description, website, X, GitHub, email — all optional, all on-chain, all readable without permission. See <a href="/docs/guide/records.html">Records &amp; profile</a>.</li><li><strong>Trade it.</strong> List it on the <a href="/docs/guide/marketplace.html">marketplace</a> or transfer it directly.</li></ul><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is not&quot;">​</a></h2><ul><li><strong>It is not a domain name.</strong> <code>alice.arc</code> will not resolve in a browser address bar. It is an on-chain identifier resolved by wallets and apps that support it.</li><li><strong>It is not permanent by default.</strong> Names are registered for a duration and must be <a href="/docs/guide/renewals.html">renewed</a>. Let one lapse and — after a grace period — someone else can take it.</li><li><strong>It is not a trademark claim.</strong> Registering a name grants no rights to it off-chain. See <a href="/docs/safety.html">Safety</a>.</li><li><strong>It is not censorship-proof against yourself.</strong> If you lose the wallet holding the token, you lose the name. There is no recovery, no support desk, and no reset. See <a href="/docs/safety.html#there-is-no-recovery">Safety</a>.</li></ul><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to &quot;How it fits together&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌─────────────┐</span></span>
<span class="line"><span>   alice.arc ───► │  Registry   │ ── which resolver answers for this name?</span></span>
<span class="line"><span>                  └──────┬──────┘</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>                  ┌──────▼──────┐</span></span>
<span class="line"><span>                  │  Resolver   │ ── addr? avatar? website?</span></span>
<span class="line"><span>                  └─────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Registrar  ── owns the ERC-721 token + expiry for each name</span></span>
<span class="line"><span>   Controller ── takes payment, enforces commit-reveal, mints via the registrar</span></span>
<span class="line"><span>   Market     ── escrow-free listings for names already registered</span></span></code></pre></div><p>Each of those is a separate contract with a separate job. The full picture, including why the split exists, is in <a href="/docs/protocol/architecture.html">Architecture</a>. The addresses are in <a href="/docs/protocol/contracts.html">Contract addresses</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/quick-start.html">Quick start</a> — get a name in about five minutes.</li><li><a href="/docs/guide/connecting-a-wallet.html">Connecting a wallet</a> — network setup and test funds.</li><li><a href="/docs/guide/pricing.html">Pricing &amp; rarity</a> — what a name costs and why length matters.</li></ul>`,21)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
